input.new_string:
import { getDb, notifications, projectMutes } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { brandId, toNotification } from "./_mappers";
import type { ListNotificationsInput } from "@/schemas/notification";
import type {
  IsoTimestamp,
  NotificationId,
  OrgId,
  Page,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Notification } from "@/types/notification";

type NewNotification = Omit<
  Notification,
  "id" | "createdAt" | "updatedAt" | "readAt" | "projectId"
> & {
  readonly projectId?: ProjectId | null;
};

  return rows.map(toNotification);
}

/** Records the actor's mute. A second mute of the same project is a no-op. */
export async function insertProjectMute(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .insert(projectMutes)
    .values({
      orgId,
      userId,
      projectId,
      createdAt: toIsoTimestamp(new Date()),
    })
    .onConflictDoNothing({
      target: [projectMutes.orgId, projectMutes.userId, projectMutes.projectId],
    })
    .run();
}

/** Lifts a mute. Missing rows are ignored so unmute stays idempotent. */
export async function deleteProjectMute(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .delete(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
        eq(projectMutes.projectId, projectId),
      ),
    )
    .run();
}

/** Projects this member has muted inside the organization. */
export async function listMutedProjectIds(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ProjectId[]> {
  const rows = getDb()
    .select({ projectId: projectMutes.projectId })
    .from(projectMutes)
    .where(
      and(orgPredicate(projectMutes.orgId, orgId), eq(projectMutes.userId, userId)),
    )
    .all();

  return rows.map((row) => brandId<ProjectId>(row.projectId));
}

/** Members who have muted this project. Used by the fan-out. */
export async function listMutedUserIds(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly UserId[]> {
  const rows = getDb()
    .select({ userId: projectMutes.userId })
    .from(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.projectId, projectId),
      ),
    )
    .all();

  return rows.map((row) => brandId<UserId>(row.userId));
}

