/**
 * Mutes a project for the actor alone. Guarded the same way as reading the
 * project. Repeating a mute does not create a second row.
 */
export async function muteProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));
  await notificationRepo.insertProjectMute(orgId, actor.userId, projectId);
}

/** Lifts the actor's mute. A project that was not muted is left unchanged. */
export async function unmuteProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));
  await notificationRepo.deleteProjectMute(orgId, actor.userId, projectId);
}

/** The actor's muted projects in this organization. */
export async function listMutedProjectIds(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly ProjectId[]> {
  assertOrgScope(actor, orgId);
  return notificationRepo.listMutedProjectIds(orgId, actor.userId);
}

